-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/bastok/Faded_Promises.lua"]={["Path"]="scripts/quests/bastok/Faded_Promises.lua",["SHA256"]="c83b285fe0f1b3559f6c00e5307fca2b8689ffebd7c743c8e3b0b9ce41cd19f9",["Text"]="-----------------------------------\n-- Faded Promises\n-----------------------------------\n-- Log ID: 1, Quest ID: 73\n-- Romualdo : !pos 133 -19 -36 237\n-- Ayame    : !pos 133 -19 34 237\n-- Kagetora : !pos -96 -2 29 236\n-- Alois    : !pos 96 -20 14 237\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.FADED_PROMISES)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.FUKURO,\n    title    = xi.title.ASSASSIN_REJECT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.NIN and\n                player:getMainLvl() >= 20 and\n                player:getFameLevel(xi.fameArea.NORG) >= 4\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Romualdo'] = quest:progressEvent(802),\n\n            onEventFinish =\n            {\n                [802] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Alois'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(805)\n                    end\n                end,\n            },\n\n            ['Ayame'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(803)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(804)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [803] = function(player, csid, option, npc)\n                    -- This event uses a very big number for cancelation, making the capture suite wrongly return 0.\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [804] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [805] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.DIARY_OF_MUKUNDA)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PALBOROUGH_MINES] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.DIARY_OF_MUKUNDA)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.DIARY_OF_MUKUNDA)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kagetora'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.DIARY_OF_MUKUNDA) then\n                        return quest:progressEvent(296)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [296] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Fallen_Comrades.lua"]={["Path"]="scripts/quests/bastok/Fallen_Comrades.lua",["SHA256"]="19439d4985571df2e4b86ae7972591094ec2630a1ece8b7cc408ecf61bdc2546",["Text"]="-----------------------------------\n-- Fallen Comrades\n-----------------------------------\n-- Log ID: 1, Quest ID: 19\n-- Pavvke : !pos 16.586 6.985 -14.843 234\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.FALLEN_COMRADES)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 550,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Pavvke'] = quest:progressEvent(90),\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Pavvke'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.SILVER_NAME_TAG, 1 } }) then\n                        if player:hasCompletedQuest(quest.areaId, quest.questId) then\n                            return quest:progressEvent(92)\n                        else\n                            return quest:progressEvent(91)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [91] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n\n                [92] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Father_Figure.lua"]={["Path"]="scripts/quests/bastok/Father_Figure.lua",["SHA256"]="c6c6aac85574a30650c9fd40ca52d136841484bdcd0cb16b5270ce5291489b22",["Text"]="-----------------------------------\n-- Father Figure\n-----------------------------------\n-- Log ID: 1, Quest ID: 29\n-- Michea : !pos -298 -16 -157 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.FATHER_FIGURE)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 2200,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_ELVAAN_GOLDSMITH) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Michea'] = quest:progressEvent(240),\n\n            onEventFinish =\n            {\n                [240] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Michea'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.SILVER_INGOT, 1 } }) then\n                        return quest:progressEvent(241)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [241] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Fear_of_Flying.lua"]={["Path"]="scripts/quests/bastok/Fear_of_Flying.lua",["SHA256"]="633a6472d3f3ea729a09ba86f5bb1ce90b4661b93306c418b588f895105f5ee5",["Text"]="-----------------------------------\n-- Fear of Flying\n-----------------------------------\n-- Log ID: 1, Quest ID: 35\n-- Kurando : !pos -23.887 3.898 0.870 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.FEAR_OF_FLYING)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.BLACK_SILK_NECKERCHIEF,\n    title    = xi.title.AIRSHIP_DENOUNCER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kurando'] = quest:progressEvent(170),\n\n            onEventFinish =\n            {\n                [170] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kurando'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.SILKWORM_EGG, 1 } }) then\n                        return quest:progressEvent(171)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [171] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kurando'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(172)\n                    else\n                        return quest:event(173):replaceDefault()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [172] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Forever_to_Hold.lua"]={["Path"]="scripts/quests/bastok/Forever_to_Hold.lua",["SHA256"]="9874652219752011e8642626c17fe1f0703639a95bbf5cc268edc48b6156faec",["Text"]="-----------------------------------\n-- Forever to Hold\n-----------------------------------\n-- Log ID: 1, Quest ID: 17\n-- Qiji    : !pos 4.257 4.898 -18.92 236\n-- Romilda : !pos 5.424 4.898 -18.699 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.FOREVER_TO_HOLD)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 300,\n    title    = xi.title.QIJIS_FRIEND,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Qiji'] = quest:progressEvent(123),\n\n            onEventFinish =\n            {\n                [123] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Qiji'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.BRASS_HAIRPIN, 1 } }) then -- Note: No trade complete.\n                        return quest:event(124)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(126)\n                    end\n                end,\n            },\n\n            ['Romilda'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.BRASS_HAIRPIN, 1 } }) then\n                        return quest:progressEvent(125)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [125] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [126] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Gourmet.lua"]={["Path"]="scripts/quests/bastok/Gourmet.lua",["SHA256"]="44d327a4211447eaf49052368182a1270ac6ad3f7db6a3ed89c8eab43e320f2f",["Text"]="-----------------------------------\n-- Gourmet\n-----------------------------------\n-- Log ID: 1, Quest ID: 12\n-- Salimah : !pos -31.687 -6.824 -73.282\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.GOURMET)\n\nquest.reward =\n{\n    title = xi.title.MOMMYS_HELPER,\n}\n\n-- Table Format: { eventId, timeMin, timeMax }\n-- NOTE: In order to iterate through these without having to change conditional\n-- logic, all time comparisons are 6 less than the actual time.\nlocal tradeItemData =\n{\n    [xi.item.SLEEPSHROOM] = { 201, 12, 24 }, -- 18:00 ~ 06:00\n    [xi.item.TREANT_BULB] = { 201,  0,  6 }, -- 06:00 ~ 12:00\n    [xi.item.WILD_ONION ] = { 202,  6, 12 }, -- 12:00 ~ 18:00\n}\n\nlocal function tradeEventFinish(player, gilReward)\n    if quest:complete(player) then\n        player:tradeComplete()\n        npcUtil.giveCurrency(player, 'gil', gilReward)\n        player:addFame(xi.fameArea.BASTOK, 10)\n        quest:setMustZone(player)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Salimah'] = quest:progressEvent(200),\n\n            onEventFinish =\n            {\n                [200] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Salimah'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if not quest:getMustZone(player) then\n                        for itemId, itemData in pairs(tradeItemData) do\n                            if npcUtil.tradeMatches(trade, { { itemId, 1 } }) then\n                                local timeOffset = VanadielHour() - 6\n\n                                if timeOffset < 0 then\n                                    timeOffset = 24 + timeOffset\n                                end\n\n                                if\n                                    timeOffset >= itemData[2] and\n                                    timeOffset < itemData[3]\n                                then\n                                    return quest:progressEvent(itemData[1], itemId)\n                                else\n                                    return quest:progressEvent(203, itemId)\n                                end\n                            end\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not quest:getMustZone(player) then\n                        return quest:event(200)\n                    else\n                        return quest:event(121)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [201] = function(player, csid, option, npc)\n                    tradeEventFinish(player, 200)\n                end,\n\n                [202] = function(player, csid, option, npc)\n                    tradeEventFinish(player, 350)\n                end,\n\n                [203] = function(player, csid, option, npc)\n                    tradeEventFinish(player, 100)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Groceries.lua"]={["Path"]="scripts/quests/bastok/Groceries.lua",["SHA256"]="17f20c8758e3b12b37a7e249c0cd01390a755adcb9b91646f03a501873b5c88e",["Text"]="-----------------------------------\n-- Groceries\n-----------------------------------\n-- Log ID: 1, Quest ID: 37\n-- Tami   : !pos 62.617 0 -68.222 234\n-- Zelman : !pos 17.095 7.704 -52.995 172\n-----------------------------------\nlocal bastokMinesID = zones[xi.zone.BASTOK_MINES]\nlocal zeruhnMinesID = zones[xi.zone.ZERUHN_MINES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.GROCERIES)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.RABBIT_MANTLE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE or\n                (status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0)\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Tami'] = quest:progressEvent(110),\n\n            onEventFinish =\n            {\n                [110] = function(player, csid, option, npc)\n                    quest:begin(player)\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.TAMIS_NOTE)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Tami'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        npcUtil.tradeMatches(trade, { { xi.item.STRIP_OF_MEAT_JERKY, 1 } })\n                    then\n                        return quest:progressEvent(113)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:messageName(bastokMinesID.text.TAMI_MY_HUSBAND)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(112)\n                    elseif questProgress == 3 then\n                        return quest:event(111)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [112] = function(player, csid, option, npc)\n                    player:addFame(xi.fameArea.BASTOK, 10)\n                    npcUtil.giveCurrency(player, 'gil', 10)\n\n                    quest:setVar(player, 'Prog', 0)\n                end,\n\n                [113] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ZERUHN_MINES] =\n        {\n            ['Zelman'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        if player:seenKeyItem(xi.keyItem.TAMIS_NOTE) then\n                            return quest:progressEvent(162)\n                        else\n                            return quest:progressEvent(161)\n                        end\n                    elseif questProgress >= 2 then\n                        return quest:messageName(zeruhnMinesID.text.ZELMAN_CANT_RUN_AROUND)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [161] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.TAMIS_NOTE)\n                end,\n\n                [162] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    player:delKeyItem(xi.keyItem.TAMIS_NOTE)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Guest_of_Hauteur.lua"]={["Path"]="scripts/quests/bastok/Guest_of_Hauteur.lua",["SHA256"]="b22674cc096a7112fa5cfe939c8ba802f7f9b96e1f06c2ee58d5daa2a3e2ce46",["Text"]="-----------------------------------\n-- Welcome to Bastok\n-----------------------------------\n-- Log ID: 1, Quest ID: 3\n-- Powhatan    : !pos -152.135 -7.48 19.014 236\n-- Steel Bones : !pos -185.766 1.999 -57.631 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.GUEST_OF_HAUTEUR)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.TARGE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3 and\n                player:getMainLvl() >= 31 and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.WELCOME_TO_BASTOK)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Powhatan'] = quest:progressEvent(55),\n\n            onEventFinish =\n            {\n                [55] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Powhatan'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.LETTER_FROM_DOMIEN) then\n                        return quest:event(56)\n                    else\n                        return quest:progressEvent(58)\n                    end\n                end,\n            },\n\n            ['Steel_Bones'] =\n            {\n                onTrigger = function(player, npc)\n                    local mainSlot = player:getEquipID(xi.slot.MAIN)\n\n                    if\n                        not player:hasKeyItem(xi.keyItem.LETTER_FROM_DOMIEN) and\n                        (mainSlot == xi.item.MAUL or\n                        mainSlot == xi.item.REPLICA_MAUL)\n                    then\n                        return quest:progressEvent(57)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_DOMIEN)\n                end,\n\n                [58] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.LETTER_FROM_DOMIEN)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Hearts_of_Mythril.lua"]={["Path"]="scripts/quests/bastok/Hearts_of_Mythril.lua",["SHA256"]="58af08d9566e203a1668a739f4eb4d61189e7f6021b22d1a56356f5a73eeab0f",["Text"]="-----------------------------------\n-- Hearts of Mythril\n-----------------------------------\n-- Log ID: 1, Quest ID: 6\n-- Elki     : !pos -17.087 -0.05 52.745 234\n-- Monument : !pos 300 -62.803 498.2 106\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.HEARTS_OF_MYTHRIL)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SITABAKI,\n    title    = xi.title.PURSUER_OF_THE_PAST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Elki'] = quest:progressEvent(41),\n\n            onEventFinish =\n            {\n                [41] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.BOUQUET_FOR_THE_PIONEERS)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Elki'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(42)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [42] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.THE_ELEVENTHS_HOUR)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Monument'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.BOUQUET_FOR_THE_PIONEERS) then\n                        return quest:progressEvent(11)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                        player:delKeyItem(xi.keyItem.BOUQUET_FOR_THE_PIONEERS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Inheritance.lua"]={["Path"]="scripts/quests/bastok/Inheritance.lua",["SHA256"]="c0b3ea543c7c0c0fbd2821b27060115ab275eaa8e99ddcf1edb24674d35079f3",["Text"]="-----------------------------------\n-- Inheritance\n-- Gumbah !pos 52 0 -36 234\n-- qm1 !pos -660 0 -338 125\n-----------------------------------\nlocal bastokMinesID = zones[xi.zone.BASTOK_MINES]\nlocal westernAltepaID = zones[xi.zone.WESTERN_ALTEPA_DESERT]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.INHERITANCE)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.SWORD_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.GREAT_SWORD) / 10 >= 250 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Gumbah'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(190):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [190] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.SWORD_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.SWORD_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Gumbah'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(194) -- complete\n                    else\n                        local hideReacquireMenuItem = (player:hasItem(xi.item.SWORD_OF_TRIALS) or player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)) and 1 or 0\n                        return quest:event(191, hideReacquireMenuItem) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.SWORD_OF_TRIALS, 1 } }) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(192) -- unfinished weapon\n                        else\n                            return quest:progressEvent(193) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [191] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.SWORD_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.SWORD_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.INHERITANCE)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [193] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [194] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                    player:addLearnedWeaponskill(xi.wsUnlock.GROUND_STRIKE)\n                    player:messageSpecial(bastokMinesID.text.GROUND_STRIKE_LEARNED)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.WESTERN_ALTEPA_DESERT] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, westernAltepaID.mob.MAHARAJA, { hide = 0 })\n                    then\n                        return quest:messageSpecial(westernAltepaID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Maharaja'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Love_and_Ice.lua"]={["Path"]="scripts/quests/bastok/Love_and_Ice.lua",["SHA256"]="32f50f5089888dbb2c3adede687f9fb07b408306b3fd321caf7f6fa58a376992",["Text"]="-----------------------------------\n-- Love and Ice\n-----------------------------------\n-- Log ID: 1, Quest ID: 43\n-- Carmelo           : !pos -146.476 -7.48 -10.889 236\n-- Mirror Pond (J-8) : !pos -96.165 1.518 -392.700 111\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.LOVE_AND_ICE)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.LAMIA_HARP,\n    title    = xi.title.SORROW_DROWNER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:seenKeyItem(xi.keyItem.CARRIER_PIGEON_LETTER)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_SIRENS_TEAR) and\n                        player:getFameLevel(xi.fameArea.BASTOK) >= 5\n                    then\n                        return quest:progressEvent(185)\n                    else\n                        return quest:event(187)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [185] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CARMELOS_SONG_SHEET)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.CARMELOS_SONG_SHEET) then\n                        return quest:progressEvent(186)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [186] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.A_TEST_OF_TRUE_LOVE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BEAUCEDINE_GLACIER] =\n        {\n            ['Mirror_Pond_1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.CARMELOS_SONG_SHEET) then\n                        return quest:progressEvent(100)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.CARMELOS_SONG_SHEET)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Lovers_in_the_Dusk.lua"]={["Path"]="scripts/quests/bastok/Lovers_in_the_Dusk.lua",["SHA256"]="af87c1cee6a531c13e9f9f2894394c28dd5b6250266d87d0955e9adedaf11fbc",["Text"]="-----------------------------------\n-- Lovers in the Dusk\n-----------------------------------\n-- Log ID: 1, Quest ID: 63\n-- Carmelo : !pos -146.476 -7.48 -10.889 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.LOVERS_IN_THE_DUSK)\n\nquest.reward =\n{\n    fame     = 70,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SIREN_FLUTE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.A_TEST_OF_TRUE_LOVE) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 6 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] = quest:progressEvent(275),\n\n            onEventFinish =\n            {\n                [275] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CHANSON_DE_LIBERTE)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] = quest:event(276),\n        },\n\n        [xi.zone.THE_SANCTUARY_OF_ZITAH] =\n        {\n            ['qm4'] =\n            {\n                onTrigger = function(player, npc)\n                    if VanadielTOTD() == xi.time.DUSK then\n                        return quest:progressEvent(204)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [204] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.CHANSON_DE_LIBERTE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] = quest:event(277):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Lure_of_the_Wildcat_Bastok.lua"]={["Path"]="scripts/quests/bastok/Lure_of_the_Wildcat_Bastok.lua",["SHA256"]="422cd7a12b24a210e366b23d219cb0bcb11f74c6d1e699ead6207f58e6eaf3be",["Text"]="-----------------------------------\n-- Lure of the Wildcat (Bastok)\n-----------------------------------\n-- Log ID: 1, Quest ID: 84\n-- Alib-Mufalib : !pos 116.08 7.372 -31.82 236\n-----------------------------------\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.LURE_OF_THE_WILDCAT)\n\nquest.reward =\n{\n    fame     = 0,\n    fameArea = xi.fameArea.BASTOK,\n    keyItem  = xi.keyItem.BLUE_INVITATION_CARD,\n}\n\nlocal wildcatNpcData =\n{\n    ['Kaede'            ] = {  0, 352 }, -- !pos 48 -6 67 236\n    ['Patient_Wheel'    ] = {  1, 354 }, -- !pos -107.988 3.898 52.557 236\n    ['Paujean'          ] = {  2, 355 }, -- !pos -93.738 4.649 34.373 236\n    ['Hilda'            ] = {  3, 356 }, -- !pos -163 -8 13 236\n    ['Tilian'           ] = {  4, 353 }, -- !pos -118.46 4.999 -68.09 236\n    ['Raibaht'          ] = {  5, 933 }, -- !pos -27 -10 -1 237\n    ['Invincible_Shield'] = {  6, 932 }, -- !pos -51.083 -11 2.126 237\n    ['Manilam'          ] = {  7, 931 }, -- !pos -57.3 -11 22.332 237\n    ['Kaela'            ] = {  8, 934 }, -- !pos 40.167 -14.999 16.073 237\n    ['Ayame'            ] = {  9, 935 }, -- !pos 133 -19 34 237\n    ['Harmodios'        ] = { 10, 430 }, -- !pos -79.928 -4.824 -135.114 235\n    ['Arawn'            ] = { 11, 429 }, -- !pos -121.492 -4 -123.923 235\n    ['Horatius'         ] = { 12, 428 }, -- !pos -158 -6 -117 235\n    ['Ken'              ] = { 13, 432 }, -- !pos -340.857 -11.003 -149.008 235\n    ['Pavel'            ] = { 14, 431 }, -- !pos -349.798 -10.002 -181.296 235\n    ['Griselda'         ] = { 15, 507 }, -- !pos -25.749 -0.044 52.36 234\n    ['Goraow'           ] = { 16, 506 }, -- !pos 38 0.1 14 234\n    ['Echo_Hawk'        ] = { 17, 505 }, -- !pos -0.965 5.999 -15.567 234\n    ['Deidogg'          ] = { 18, 504 }, -- !pos -13 7 29 234\n    ['Vaghron'          ] = { 19, 503 }, -- !pos -39.162 -1 -92.147 234\n}\n\nlocal wildcatOnTrigger = function(player, npc)\n    local npcData = wildcatNpcData[npc:getName()]\n\n    if not quest:isVarBitsSet(player, 'Prog', npcData[1]) then\n        return quest:progressEvent(npcData[2])\n    end\nend\n\nlocal wildcatOnEventFinish = function(player, csid, option, npc)\n    quest:setVarBit(player, 'Prog', wildcatNpcData[npc:getName()][1])\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.settings.main.ENABLE_TOAU == 1\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Alib-Mufalib'] = quest:progressEvent(357),\n\n            onEventFinish =\n            {\n                [357] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BLUE_SENTINEL_BADGE)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Arawn'    ] = wildcatOnTrigger,\n            ['Harmodios'] = wildcatOnTrigger,\n            ['Horatius' ] = wildcatOnTrigger,\n            ['Ken'      ] = wildcatOnTrigger,\n            ['Pavel'    ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [428] = wildcatOnEventFinish,\n                [429] = wildcatOnEventFinish,\n                [430] = wildcatOnEventFinish,\n                [431] = wildcatOnEventFinish,\n                [432] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Deidogg'  ] = wildcatOnTrigger,\n            ['Echo_Hawk'] = wildcatOnTrigger,\n            ['Goraow'   ] = wildcatOnTrigger,\n            ['Griselda' ] = wildcatOnTrigger,\n            ['Vaghron'  ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [503] = wildcatOnEventFinish,\n                [504] = wildcatOnEventFinish,\n                [505] = wildcatOnEventFinish,\n                [506] = wildcatOnEventFinish,\n                [507] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'            ] = wildcatOnTrigger,\n            ['Invincible_Shield'] = wildcatOnTrigger,\n            ['Kaela'            ] = wildcatOnTrigger,\n            ['Manilam'          ] = wildcatOnTrigger,\n            ['Raibaht'          ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [931] = wildcatOnEventFinish,\n                [932] = wildcatOnEventFinish,\n                [933] = wildcatOnEventFinish,\n                [934] = wildcatOnEventFinish,\n                [935] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Alib-Mufalib'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(358)\n                    elseif utils.mask.isFull(questProgress, 20) then\n                        return quest:progressEvent(360)\n                    else\n                        return quest:event(359)\n                    end\n                end,\n            },\n\n            ['Hilda'        ] = wildcatOnTrigger,\n            ['Kaede'        ] = wildcatOnTrigger,\n            ['Patient_Wheel'] = wildcatOnTrigger,\n            ['Paujean'      ] = wildcatOnTrigger,\n            ['Tilian'       ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [352] = wildcatOnEventFinish,\n                [353] = wildcatOnEventFinish,\n                [354] = wildcatOnEventFinish,\n                [355] = wildcatOnEventFinish,\n                [356] = wildcatOnEventFinish,\n\n                [360] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.BLUE_SENTINEL_BADGE)\n                    player:messageSpecial(portBastokID.text.KEYITEM_LOST, xi.keyItem.BLUE_SENTINEL_BADGE)\n\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/MNK_AF1_Ghosts_of_the_Past.lua"]={["Path"]="scripts/quests/bastok/MNK_AF1_Ghosts_of_the_Past.lua",["SHA256"]="c61f52ac711378d954dc17803d394f937240384163afe46c4a0c7dc87d8fc361",["Text"]="-----------------------------------\n-- Ghosts of the Past\n-----------------------------------\n-- Log ID: 1, Quest ID: 51\n-- Oggbi : !pos -159 -7 5 236\n-- qm4   : !pos -174 0 369 196\n-----------------------------------\nlocal gusgenMinesID = zones[xi.zone.GUSGEN_MINES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.GHOSTS_OF_THE_PAST)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.BEAT_CESTI,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.GUSGEN_MINES] =\n        {\n            ['qm4'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if trade:getItemQty(xi.item.PICKAXE) > 0 then\n                        return quest:messageSpecial(gusgenMinesID.text.YOU_CANNOT_EVEN_DIG, xi.item.PICKAXE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Oggbi'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() == xi.job.MNK and\n                        player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n                    then\n                        return quest:progressEvent(231)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [231] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GUSGEN_MINES] =\n        {\n            ['qm4'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        trade:getItemQty(xi.item.PICKAXE) > 0 and\n                        not player:hasItem(xi.item.MINERS_PENDANT) and\n                        not GetMobByID(gusgenMinesID.mob.WANDERING_GHOST):isSpawned()\n                    then\n                        SpawnMob(gusgenMinesID.mob.WANDERING_GHOST):updateClaim(player)\n                        return quest:messageSpecial(gusgenMinesID.text.YOU_CANNOT_EVEN_DIG, xi.item.PICKAXE)\n                    else\n                        return player:messageSpecial(gusgenMinesID.text.YOU_CANNOT_EVEN_DIG, xi.item.PICKAXE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Oggbi'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.MINERS_PENDANT, 1 } }) then\n                        return quest:progressEvent(232)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [232] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n\n                        xi.quest.setMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.THE_FIRST_MEETING)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.GUSGEN_MINES] =\n        {\n            ['qm4'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if trade:getItemQty(xi.item.PICKAXE) > 0 then\n                        return quest:messageSpecial(gusgenMinesID.text.YOU_CANNOT_EVEN_DIG, xi.item.PICKAXE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/MNK_AF2_The_First_Meeting.lua"]={["Path"]="scripts/quests/bastok/MNK_AF2_The_First_Meeting.lua",["SHA256"]="cf9df34e7042fe2c727f78e430c93da15fd65fa08e375848c1a05b3fe3c96717",["Text"]="-----------------------------------\n-- The First Meeting\n-----------------------------------\n-- Log ID: 1, Quest ID: 52\n-- Oggbi         : !pos -159 -7 5 236\n-- Hide Flap (2) : !pos -124 3 -43 149\n-----------------------------------\nlocal davoiID = zones[xi.zone.DAVOI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_FIRST_MEETING)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.TEMPLE_GAITERS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                not quest:getMustZone(player) and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.GHOSTS_OF_THE_PAST) and\n                player:getMainJob() == xi.job.MNK and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Oggbi'] = quest:progressEvent(233),\n\n            onEventFinish =\n            {\n                [233] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.DAVOI] =\n        {\n            ['Hide_Flap_2'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:checkDistance(npc) <= 1 then\n                        return quest:progressEvent(108)\n                    else\n                        return quest:messageSpecial(davoiID.text.CLOSER_TO_SEARCH)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [108] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        return\n                    end\n\n                    if player:hasKeyItem(xi.keyItem.SAN_DORIAN_MARTIAL_ARTS_SCROLL) then\n                        player:messageSpecial(davoiID.text.YOU_FIND_NOTHING)\n                    elseif quest:getLocalVar(player, 'nmKilled') == 3 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SAN_DORIAN_MARTIAL_ARTS_SCROLL)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.LETTER_FROM_DALZAKK) and\n                        not GetMobByID(davoiID.mob.BILOPDOP):isSpawned() and\n                        not GetMobByID(davoiID.mob.DELOKNOK):isSpawned()\n                    then\n                        player:messageSpecial(davoiID.text.YOU_FIND_NOTHING)\n                        SpawnMob(davoiID.mob.BILOPDOP):updateClaim(player)\n                        SpawnMob(davoiID.mob.DELOKNOK):updateEnmity(player)\n                    else\n                        player:messageSpecial(davoiID.text.YOU_FIND_NOTHING)\n                    end\n                end,\n            },\n\n            ['Bilopdop'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if not player:hasKeyItem(xi.keyItem.SAN_DORIAN_MARTIAL_ARTS_SCROLL) then\n                        local nmStatus = quest:getLocalVar(player, 'nmKilled')\n\n                        quest:setLocalVar(player, 'nmKilled', utils.mask.setBit(nmStatus, 0, true))\n                    end\n                end,\n            },\n\n            ['Deloknok'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if not player:hasKeyItem(xi.keyItem.SAN_DORIAN_MARTIAL_ARTS_SCROLL) then\n                        local nmStatus = quest:getLocalVar(player, 'nmKilled')\n\n                        quest:setLocalVar(player, 'nmKilled', utils.mask.setBit(nmStatus, 1, true))\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.FEIYIN] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.QUBIA_ARENA and\n                    not player:hasKeyItem(xi.keyItem.LETTER_FROM_DALZAKK)\n                then\n                    return 16\n                end\n            end,\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_DALZAKK)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Oggbi'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.LETTER_FROM_DALZAKK) and\n                        player:hasKeyItem(xi.keyItem.SAN_DORIAN_MARTIAL_ARTS_SCROLL)\n                    then\n                        return quest:progressEvent(234)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [234] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.LETTER_FROM_DALZAKK)\n                        player:delKeyItem(xi.keyItem.SAN_DORIAN_MARTIAL_ARTS_SCROLL)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/MNK_AF3_True_Strength.lua"]={["Path"]="scripts/quests/bastok/MNK_AF3_True_Strength.lua",["SHA256"]="e91750d521701b2992ae5bb0616760ba378a4a69587594d06164cd37e74ca748",["Text"]="-----------------------------------\n-- True Strength\n-----------------------------------\n-- Log ID: 1, Quest ID: 53\n-- Ayame           : !pos 133 -19 34 237\n-- qm_truestrength : !pos -100 -71 -132 151\n-----------------------------------\nlocal oztrojaID = zones[xi.zone.CASTLE_OZTROJA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.TRUE_STRENGTH)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.TEMPLE_HOSE,\n    title    = xi.title.PARAGON_OF_MONK_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_FIRST_MEETING) and\n                player:getMainJob() == xi.job.MNK and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] = quest:progressEvent(748),\n\n            onEventFinish =\n            {\n                [748] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CASTLE_OZTROJA] =\n        {\n            ['qm_truestrength'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeMatches(trade, { { xi.item.BOTTLE_OF_YAGUDO_DRINK, 1 } }) and\n                        not player:hasItem(xi.item.XALMO_FEATHER) and\n                        npcUtil.popFromQM(player, npc, oztrojaID.mob.HUU_XALMO_THE_SAVAGE, { hide = 0 })\n                    then\n                        player:tradeComplete()\n\n                        return quest:messageSpecial(oztrojaID.text.YOU_HOLD, xi.item.BOTTLE_OF_YAGUDO_DRINK)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.XALMO_FEATHER, 1 } }) then\n                        return quest:progressEvent(749)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [749] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Mean_Machine.lua"]={["Path"]="scripts/quests/bastok/Mean_Machine.lua",["SHA256"]="49dc6f5bcd42e4b94ba2c08d527a11e1e7fbceb27a0b4cdc5dd342b36786230d",["Text"]="-----------------------------------\n-- Mean Machine\n-----------------------------------\n-- Log ID: 1, Quest ID: 25\n-- Unlucky Rat : -59.724 1.999 30.179 237\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.MEAN_MACHINE)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SCROLL_OF_WARP,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Unlucky_Rat'] = quest:progressEvent(556),\n\n            onEventFinish =\n            {\n                [556] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Unlucky_Rat'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.VIAL_OF_SLIME_OIL, 1 } }) then\n                        return quest:progressEvent(557)\n                    end\n                end,\n\n                onTrigger = quest:event(559),\n            },\n\n            onEventFinish =\n            {\n                [557] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Minesweeper.lua"]={["Path"]="scripts/quests/bastok/Minesweeper.lua",["SHA256"]="7acd504b9dd0922bb09d9b68565701e35303f6f20905a33443816943a9d9face",["Text"]="-----------------------------------\n-- Minesweeper\n-----------------------------------\n-- Log ID: 1, Quest ID: 39\n-- Gerbaum : !pos -119.899 -3.492 -74.651 234\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.MINESWEEPER)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 150,\n    title    = xi.title.ZERUHN_SWEEPER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Gerbaum'] = quest:progressEvent(108),\n\n            onEventFinish =\n            {\n                [108] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Gerbaum'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.PINCH_OF_ZERUHN_SOOT, 3 } }) then\n                        return quest:progressEvent(109)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [109] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Mom_the_Adventurer.lua"]={["Path"]="scripts/quests/bastok/Mom_the_Adventurer.lua",["SHA256"]="8eb8ab1ffaf215e0d604248b712d23c8ee00addef6006ca2cef4daf0fac20d5f",["Text"]="-----------------------------------\n-- Mom, the Adventurer?\n-----------------------------------\n-- Log ID: 1, Quest ID: 21\n-- Nbu Latteh : !pos -114.777 -4 -113.301 235\n-- Roh Latteh : !pos -11.823 6.999 -9.249 234\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.MOM_THE_ADVENTURER)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    title    = xi.title.RINGBEARER,\n}\n\nlocal handleEventFinish = function(player, csid, option, npc)\n    local gilReward = csid == 233 and 200 or 100\n\n    if quest:complete(player) then\n        player:delKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH)\n        npcUtil.giveCurrency(player, 'gil', gilReward)\n        quest:setMustZone(player)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Nbu_Latteh'] = quest:progressEvent(230),\n\n            onEventFinish =\n            {\n                [230] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.FIRE_CRYSTAL) then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Nbu_Latteh'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH) then\n                        if player:seenKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH) then\n                            return quest:progressEvent(234)\n                        else\n                            return quest:progressEvent(233)\n                        end\n                    else\n                        return quest:event(231)\n                    end\n                end,\n            },\n\n            ['Parnika'] = quest:event(232),\n\n            onEventFinish =\n            {\n                [233] = handleEventFinish,\n                [234] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Roh_Latteh'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeMatches(trade, { { xi.item.COPPER_RING, 1 } }) and\n                        not player:hasKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH)\n                    then\n                        return quest:progressEvent(95)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [95] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_ROH_LATTEH)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Nbu_Latteh'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Allow quest completion regardless of fame level.\n                    if player:hasKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH) then\n                        if player:seenKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH) then\n                            return quest:progressEvent(234)\n                        else\n                            return quest:progressEvent(233)\n                        end\n                    end\n\n                    -- Allow quest repeat at Bastok fame 1.\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if\n                        player:getFameLevel(xi.fameArea.BASTOK) == 1 and\n                        questProgress == 0\n                    then\n                        return quest:progressEvent(230)\n\n                    -- Now you are stuck.\n                    elseif questProgress == 1 then\n                        return quest:event(231)\n                    end\n                end,\n            },\n\n            ['Parnika'] = quest:event(232),\n\n            onEventFinish =\n            {\n                [230] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.FIRE_CRYSTAL) then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [233] = handleEventFinish,\n                [234] = handleEventFinish,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Roh_Latteh'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        not player:hasKeyItem(xi.keyItem.LETTER_FROM_ROH_LATTEH) and\n                        npcUtil.tradeMatches(trade, { { xi.item.COPPER_RING, 1 } })\n                    then\n                        return quest:progressEvent(95)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [95] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_ROH_LATTEH)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Out_of_Ones_Shell.lua"]={["Path"]="scripts/quests/bastok/Out_of_Ones_Shell.lua",["SHA256"]="cdea458f2c460617f8b220930497a1b9ca00667664ec51ce78269a9a25514a51",["Text"]="-----------------------------------\n-- Out of One's Shell\n-----------------------------------\n-- Log ID: 1, Quest ID: 5\n-- Ronan : !pos 84.712 -8.772 20.301 236\n-----------------------------------\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.OUT_OF_ONES_SHELL)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.MONKS_HEADGEAR,\n    title    = xi.title.SHELL_OUTER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_QUADAVS_CURSE) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ronan'] = quest:progressEvent(82),\n\n            onEventFinish =\n            {\n                [82] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ronan'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeMatches(trade, { { xi.item.SHELL_BUG, 3 } })\n                    then\n                        return quest:progressEvent(84)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        if not quest:getMustZone(player) then\n                            return quest:progressEvent(86)\n                        else\n                            return quest:event(85)\n                        end\n                    else\n                        return quest:messageName(portBastokID.text.RONAN_DIALOG_1)\n                    end\n                end,\n            },\n\n            ['Mine_Konte'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(83)\n                    end\n                end,\n            },\n\n            ['Panana'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(83)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [84] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    quest:setVar(player, 'Prog', 1)\n                    quest:setMustZone(player)\n                end,\n\n                [86] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Corann'] = quest:event(88):replaceDefault(),\n            ['Ronan']  = quest:event(89):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Out_of_the_Depths.lua"]={["Path"]="scripts/quests/bastok/Out_of_the_Depths.lua",["SHA256"]="e780fd2ce0b42743e81e65c8de92fcab6116338c002a82a4967073ff9ed2ef8e",["Text"]="-----------------------------------\n-- Out of the Depths\n-----------------------------------\n-- Log ID: 1, Quest ID: 75\n-- Ayame     !pos 132.904 -18.983 34.106\n-- Ravorara  !pos -150.614 -6.000 -8.320\n-- Brakobrik !pos 165.573 12.000 -89.774\n-- Pavvke    !pos 15.820 6.985 -14.324\n-----------------------------------\nlocal oldtonID = zones[xi.zone.OLDTON_MOVALPOLOS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.OUT_OF_THE_DEPTHS)\n\nquest.reward =\n{\n    fame     = 80,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 1200,\n    title    = xi.title.TRASH_COLLECTOR,\n}\n\nlocal kiCheck = function(player)\n    if\n        player:hasKeyItem(xi.keyItem.DUSTY_TOME) or\n        player:hasKeyItem(xi.keyItem.POINTED_JUG) or\n        player:hasKeyItem(xi.keyItem.CRACKED_CLUB) or\n        player:hasKeyItem(xi.keyItem.PEELING_HAIRPIN)\n    then\n        return true\n    else\n        return false\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] = quest:progressEvent(859),\n\n            onEventFinish =\n            {\n                [859] = function(player, csid, option, npc)\n                    if option == 3 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] = quest:event(860):setPriority(101) -- Reminder\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ravorara'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(307)\n                    elseif\n                        progress <= 3 and\n                        kiCheck(player)\n                    then -- Always checks the KIs in this order\n                        if player:hasKeyItem(xi.keyItem.DUSTY_TOME) then\n                            return quest:progressEvent(309, 0, 1, 0, xi.keyItem.DUSTY_TOME)\n                        elseif player:hasKeyItem(xi.keyItem.POINTED_JUG) then\n                            return quest:progressEvent(309, 0, 2, 0, xi.keyItem.POINTED_JUG)\n                        elseif player:hasKeyItem(xi.keyItem.CRACKED_CLUB) then\n                            return quest:progressEvent(309, 0, 3, 0, xi.keyItem.CRACKED_CLUB)\n                        elseif player:hasKeyItem(xi.keyItem.PEELING_HAIRPIN) then\n                            return quest:progressEvent(309, 0, 4, 0, xi.keyItem.PEELING_HAIRPIN)\n                        end\n                    elseif\n                        progress == 3 and\n                        not kiCheck(player) and\n                        player:hasKeyItem(xi.keyItem.OLD_NAMETAG)\n                    then\n                        return quest:progressEvent(309, 0, 5, 0, xi.keyItem.OLD_NAMETAG)\n                    elseif progress == 4 then\n                        return quest:event(311)\n                    else\n                        return quest:event(308)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [307] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [309] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.DUSTY_TOME)\n                        quest:setVarBit(player, 'Option', 0)\n                        npcUtil.giveCurrency(player, 'gil', 100)\n                    elseif option == 2 then\n                        player:delKeyItem(xi.keyItem.POINTED_JUG)\n                        quest:setVarBit(player, 'Option', 1)\n                        npcUtil.giveCurrency(player, 'gil', 200)\n                    elseif option == 3 then\n                        player:delKeyItem(xi.keyItem.CRACKED_CLUB)\n                        quest:setVarBit(player, 'Option', 2)\n                        npcUtil.giveCurrency(player, 'gil', 300)\n                    elseif option == 4 then\n                        player:delKeyItem(xi.keyItem.PEELING_HAIRPIN)\n                        quest:setVarBit(player, 'Option', 3)\n                        npcUtil.giveCurrency(player, 'gil', 400)\n                    elseif option == 5 then\n                        player:delKeyItem(xi.keyItem.OLD_NAMETAG)\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Pavvke'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(238):setPriority(1005) -- Ensures this plays before the start of the quest \"Fallen Comrades\" as observed in captures.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [238] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Brakobrik'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressCutscene(2, 0, xi.item.PINCH_OF_HOARY_BOMB_ASH)\n                    elseif progress == 2 then\n                        return quest:messageSpecial(oldtonID.text.KILLING_BOMBS, 0, xi.item.PINCH_OF_HOARY_BOMB_ASH)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local bombAshCount = utils.clamp(trade:getItemQty(xi.item.PINCH_OF_HOARY_BOMB_ASH), 0, 4)\n                    local option       = quest:getVar(player, 'Option')\n                    local dustyTome    = player:hasKeyItem(xi.keyItem.DUSTY_TOME) and 1 or 0\n\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        bombAshCount > 0\n                    then\n                        if npcUtil.tradeMatches(trade, { { xi.item.PINCH_OF_HOARY_BOMB_ASH, bombAshCount } }) then\n                            -- Player has traded 1, 2, 3 or 4 ash and does not have associated KI.\n                            if\n                                (bombAshCount == 4 and not player:hasKeyItem(xi.keyItem.PEELING_HAIRPIN)) or\n                                (bombAshCount == 3 and not player:hasKeyItem(xi.keyItem.CRACKED_CLUB)) or\n                                (bombAshCount == 2 and not player:hasKeyItem(xi.keyItem.POINTED_JUG)) or\n                                (bombAshCount == 1 and not player:hasKeyItem(xi.keyItem.DUSTY_TOME) and option < 15)\n                            then\n                                return quest:progressCutscene(4, 0, 0, bombAshCount) -- Both selections return option = #bombAsh\n\n                            -- Depending on where the player is in the quest this interaction changes\n                            elseif bombAshCount == 1 and option == 15 then\n                                return quest:progressCutscene(4, 5, 4, 1, 1, dustyTome) -- Selection 1 returns 1 selection 2 returns 5\n\n                            -- Player has the key item for the number of ash traded\n                            else\n                                return quest:progressCutscene(4, 0, 0, 0, 0, 1) -- Both selections return option 6\n                            end\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [4] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.DUSTY_TOME)\n                    elseif option == 2 then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.POINTED_JUG)\n                    elseif option == 3 then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.CRACKED_CLUB)\n                    elseif option == 4 then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.PEELING_HAIRPIN)\n                    elseif option == 5 and quest:getVar(player, 'Option') == 15 then\n                        player:tradeComplete()\n                        npcUtil.giveKeyItem(player, xi.keyItem.OLD_NAMETAG)\n                        quest:setVar(player, 'Prog', 3)\n                    elseif option == 6 then\n                        player:tradeComplete()\n                        player:messageSpecial(oldtonID.text.REFUSES_TO_GIVE_ANOTHER)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/PUP_LB_Achieving_True_Power.lua"]={["Path"]="scripts/quests/bastok/PUP_LB_Achieving_True_Power.lua",["SHA256"]="25942df3b12cf7a4e1e2f51ace7961adbdeb3fdf4d57345cf021f1206ff19aa2",["Text"]="-----------------------------------\n-- Achieving True Power\n-----------------------------------\n-- Log ID: 1, Quest ID: 85\n-----------------------------------\nlocal navukgoID = zones[xi.zone.NAVUKGO_EXECUTION_CHAMBER]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.ACHIEVING_TRUE_POWER)\n\nquest.reward =\n{\n    title = xi.title.MASTER_OF_MANIPULATION,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PUPPETMASTER_BLUES) and\n                player:getMainJob() == xi.job.PUP and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Shamarhaan'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(441, xi.automaton.getModelId(player))\n                end,\n            },\n\n            onEventFinish =\n            {\n                [441] = function(player, csid, option, npc)\n                    return quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() == xi.job.PUP and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Shamarhaan'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if trade:getItemQty(xi.item.PUPPETMASTERS_TESTIMONY) > 0 then\n                        return quest:progressEvent(443)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(442)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [443] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:setPos(-659.106, -9.126, -194.577, 213, xi.zone.NAVUKGO_EXECUTION_CHAMBER)\n                end,\n            },\n        },\n\n        [xi.zone.NAVUKGO_EXECUTION_CHAMBER] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.ACHIEVING_TRUE_POWER then\n                        if player:getLevelCap() == 70 then\n                            player:setLevelCap(75)\n                            player:messageSpecial(navukgoID.text.YOUR_LEVEL_LIMIT_IS_NOW_75)\n                        end\n\n                        npcUtil.giveItem(player, { xi.item.SCROLL_OF_INSTANT_WARP })\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Shamarhaan'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(444):replaceDefault()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Past_Perfect.lua"]={["Path"]="scripts/quests/bastok/Past_Perfect.lua",["SHA256"]="494152f6a7c062926eccc3f99479eaeb3a45834c236cd1430c5176ce5c6f4143",["Text"]="-----------------------------------\n-- Past Perfect\n-----------------------------------\n-- Log ID: 1, Quest ID: 23\n-- Evi : !pos -4.656 -2.101 1.664 236\n-- qm2 : !pos -201 16 80 108\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.PAST_PERFECT)\n\nquest.reward =\n{\n    item     = xi.item.SCALE_MAIL,\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Evi'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(21)\n                    else\n                        return quest:progressEvent(130)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [21] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [130] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.TATTERED_MISSION_ORDERS) then\n                        return quest:keyItem(xi.keyItem.TATTERED_MISSION_ORDERS)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Evi'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TATTERED_MISSION_ORDERS) then\n                        return quest:progressEvent(131)\n                    else\n                        return quest:event(104)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [131] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.TATTERED_MISSION_ORDERS)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Evi'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('EviDialog') == 0 then\n                        return quest:progressEvent(21)\n                    else\n                        return quest:event(104)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [21] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Return_to_the_Depths.lua"]={["Path"]="scripts/quests/bastok/Return_to_the_Depths.lua",["SHA256"]="ade46900424d27b7835c4bae6eaa46cc5307613812300c3551af785015a497fd",["Text"]="-----------------------------------\n-- Return to the Depths\n-----------------------------------\n-- Log ID: 1, Quest ID: 78\n-----------------------------------\n-- Area: Metalworks\n-- NPC: Ayame !pos 132 -18 33 237\n-- NPC: Rakorok !pos 158 13 -42 11\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.RETURN_TO_THE_DEPTHS)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.BOWYER_RING,\n    title    = xi.title.GOBLIN_IN_DISGUISE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 5 and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.A_QUESTION_OF_FAITH)\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] = quest:progressEvent(879),\n\n            onEventFinish =\n            {\n                [879] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:event(880)\n                    elseif progress == 10 then\n                        return quest:progressEvent(881)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [881] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            onZoneIn = function(player)\n                local progress = quest:getVar(player, 'Prog')\n\n                if progress == 0 then\n                    return 40\n                elseif progress == 5 then\n                    return 41\n                end\n            end,\n\n            ['Tarnotik'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') >= 7 and\n                        npcUtil.tradeMatches(trade, { { xi.item.BOTTLE_OF_AHRIMAN_TEARS, 1 } })\n                    then\n                        return quest:progressEvent(44)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 6 then\n                        return quest:progressEvent(42, 11, 131456, 384, 0, xi.item.MISAREAUX_GARLIC)\n                    elseif progress >= 7 then\n                        return quest:event(43):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [40] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [41] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [42] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n\n                [44] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 8)\n                    player:tradeComplete()\n                    player:setPos(-93.657, -120.000, -583.561, 232, xi.zone.MINE_SHAFT_2716)\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Muckvix'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.MISAREAUX_GARLIC, 1 } })\n                    then\n                        return quest:progressEvent(99, 1, 1, 3, 0, xi.item.MISAREAUX_GARLIC)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 2 then\n                        return quest:event(46):oncePerZone()\n                    elseif\n                        progress == 4 and\n                        player:hasKeyItem(xi.keyItem.LETTER_FROM_MAGRIFFON) and\n                        player:hasKeyItem(xi.keyItem.PROVIDENCE_POT)\n                    then\n                        return quest:progressEvent(100)\n                    elseif progress == 5 then\n                        return quest:event(47):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [99] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_MUCKVIX)\n                    npcUtil.giveCurrency(player, 'gil', 2000)\n                end,\n\n                [100] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    npcUtil.giveKeyItem(player, xi.keyItem.PUNGENT_PROVIDENCE_POT)\n                    player:delKeyItem(xi.keyItem.PROVIDENCE_POT)\n                    player:delKeyItem(xi.keyItem.LETTER_FROM_MAGRIFFON)\n                end,\n            },\n        },\n\n        [xi.zone.KAZHAM] =\n        {\n            ['Magriffon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        trade:getGil() == 10000\n                    then\n                        return quest:progressEvent(301, 1, xi.keyItem.PROVIDENCE_POT)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        player:hasKeyItem(xi.keyItem.LETTER_FROM_MUCKVIX)\n                    then\n                        return quest:progressEvent(299, 75, xi.keyItem.PROVIDENCE_POT, 10000)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [299] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    player:delKeyItem(xi.keyItem.LETTER_FROM_MUCKVIX)\n                end,\n\n                [301] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.PROVIDENCE_POT)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_MAGRIFFON)\n                end,\n            },\n        },\n\n        [xi.zone.MINE_SHAFT_2716] =\n        {\n            ['_0d0'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 8 then\n                        return quest:progressEvent(5, 1, 131456, 384, 0, xi.item.MISAREAUX_GARLIC)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 9)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.RETURN_TO_THE_DEPTHS then\n                        quest:setVar(player, 'Prog', 10)\n                        npcUtil.giveCurrency(player, 'gil', 10000)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(882)\n                end,\n            },\n        },\n\n        [xi.zone.OLDTON_MOVALPOLOS] =\n        {\n            ['Tarnotik'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.BOTTLE_OF_AHRIMAN_TEARS, 1 } }) then\n                        return quest:event(44)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(45):oncePerZone()\n                end,\n            },\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:setPos(-93.657, -120.000, -583.561, 232, xi.zone.MINE_SHAFT_2716)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ravorara'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.PUNGENT_PROVIDENCE_POT) then\n                        return quest:progressEvent(313, 0, 0, 0, xi.keyItem.PUNGENT_PROVIDENCE_POT)\n                    else\n                        return quest:event(314)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [313] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveCurrency(player, 'gil', 1000)\n                        player:delKeyItem(xi.keyItem.PUNGENT_PROVIDENCE_POT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
